import json,numpy as np
m=json.load(open('/app/output/frames/initial_meta.json'));c=m['cameras']['egocentric_mirrored_camera'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:3,:3];t=E[:3,3];C=-R.T@t
for uv in [(267,172),(270,157),(270,170),(275,170)]:
 d=R.T@np.linalg.inv(K)@np.array([*uv,1]);
 for z in [.045,.05,.055,.06]:
  p=C+(z-C[2])/d[2]*d
  print(uv,z,np.round(p,3))
